                output("joined", "Склеенные каналы", 'std::cout << "Air";\nstd::cout << "lock" << " 2";', "Airlock 2", ["Новая инструкция не означает новую строку.", "Единственный пробел находится перед цифрой 2."], "Air и lock соединяются напрямую; пробел появляется только из последнего литерала."),
                code("bridge", "Почините табло", 'Табло выводит DockReady слитно. Напишите программу, которая выводит Dock и Ready на отдельных строках.', 'std::cout << "Dock\\nReady";', [("", "Dock\nReady")], ["Нужен разделитель между словами.", "Используйте \\n, а не пробел."], "Перенос отделяет второе состояние, не меняя сами слова."),
                choice("source", "Пробелы исходника", 'Изменится ли вывод std::cout << "A"; если записать инструкцию с отступом на следующей строке исходного файла?', ["Да, появится отступ", "Нет, пробелы вне литерала не выводятся", "Да, появится пустая строка"], 1, ["Важны символы внутри кавычек.", "Оформление исходного кода и результат — разные вещи."], "Отступ облегчает чтение исходника и не является командой вывода."),
