                output("comment", "Комментарий или сообщение?", 'std::cout << "// online"; // offline', "// online", ["Посмотрите, что находится внутри кавычек.", "Комментарий начинается только после закрытия литерала и точки с запятой."], "Внутри строкового литерала // не является началом комментария."),
                code("path", "Путь к архиву", 'Выведите ровно C:\\Lab\\notes.txt. Это учебная строка, а не обращение к файлу.', 'std::cout << "C:\\\\Lab\\\\notes.txt";', [("", "C:\\Lab\\notes.txt")], ["Каждую обратную черту в литерале нужно удвоить.", "Особенно внимательно к \\n: без удвоения это перенос строки."], "\\\\ превращается в одну обратную черту; файлы программа не открывает."),
